(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  await sleep(1500);
  const pinBox = Array.from(document.querySelectorAll('input[type=text],input[type=password]')).filter(i => i.offsetParent!==null && (i.maxLength===4 || /pin/i.test(i.id||'')));
  const txt = (document.body.innerText||'').replace(/\s+/g,' ').slice(0, 420);
  const boxesVis = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null).length;
  return JSON.stringify({url: location.href, txt, pinBox: pinBox.length, boxesVis});
})()
